展开或折叠组.code:
#target photoshop
(function collapseAllGroups() {
    if (app.documents.length === 0) return;
    var d = app.activeDocument;
    var cl = d.activeLayer;
    var ta = cl;
    while (ta.parent && ta.parent.typename !== 'Document') {
        ta = ta.parent;
    }
    if (ta.typename !== 'LayerSet') return;
    try {
        executeAction(stringIDToTypeID('collapseAllGroupsEvent'), new ActionDescriptor(), DialogModes.NO);
    } catch (e) {}
    if (ta.layers.length > 0) d.activeLayer = ta.layers[0];
    else d.activeLayer = ta;
})();

