解锁所有图层.code:
#target photoshop
(function unlockAllLayers() {
    if (app.documents.length === 0) return;
    var d = app.activeDocument;
    function doUnlock() {
        try {
            if (d.backgroundLayer) d.backgroundLayer.isBackgroundLayer = false;
        } catch (e) {}
        var ts = 0;
        try {
            var r2 = new ActionReference();
            r2.putProperty(charIDToTypeID('Prpr'), stringIDToTypeID('numberOfLayers'));
            r2.putEnumerated(charIDToTypeID('Dcmn'), charIDToTypeID('Ordn'), charIDToTypeID('Trgt'));
            ts = executeActionGet(r2).getInteger(stringIDToTypeID('numberOfLayers'));
        } catch (e) { return; }
        for (var j = 1; j <= ts; j++) {
            try {
                var r3 = new ActionReference();
                r3.putIndex(charIDToTypeID('Lyr '), j);
                var ld = executeActionGet(r3);
                if (typeIDToStringID(ld.getEnumerationValue(stringIDToTypeID('layerSection'))) !== 'layerSectionEnd' && ld.hasKey(stringIDToTypeID('layerLocking'))) {
                    var lk = ld.getObjectValue(stringIDToTypeID('layerLocking'));
                    var d2 = new ActionDescriptor();
                    var rf = new ActionReference();
                    rf.putIdentifier(charIDToTypeID('Lyr '), ld.getInteger(stringIDToTypeID('layerID')));
                    d2.putReference(charIDToTypeID('null'), rf);
                    var lp = new ActionDescriptor();
                    var ks = ['protectAll', 'protectComposite', 'protectPosition', 'protectTrans', 'protectArtboardAutonest'];
                    var sh = false;
                    for (var k = 0; k < ks.length; k++) {
                        var kid = stringIDToTypeID(ks[k]);
                        if (lk.hasKey(kid) && lk.getBoolean(kid) === true) {
                            lp.putBoolean(kid, false);
                            sh = true;
                        }
                    }
                    if (sh) {
                        d2.putObject(charIDToTypeID('T   '), stringIDToTypeID('layerLocking'), lp);
                        executeAction(charIDToTypeID('setd'), d2, DialogModes.NO);
                    }
                }
            } catch (e) {}
        }
    }
    d.suspendHistory('解锁所有图层', 'doUnlock()');
})();

导出指定尺寸.code:
// param: {"k":"target","t":"select","n":"导出对象","d":"doc","o":[["doc","整个文档"],["layer","当前图层（裁到图层范围）"]]}
// param: {"k":"mode","t":"select","n":"缩放方式","d":"fit","o":[["fit","适配：长边不超过目标"],["exact","精确：强制到目标宽高"],["scale","倍数：宽度字段填倍率"]]}
// param: {"k":"width","t":"number","n":"宽度","d":1920,"min":0,"max":40000,"unit":"px","hint":"倍数模式下填倍率，2 = 200%"}
// param: {"k":"height","t":"number","n":"高度","d":0,"min":0,"max":40000,"unit":"px","hint":"0 = 留空，按宽度比例算"}
// param: {"k":"format","t":"select","n":"格式","d":"png","o":[["png","PNG（保留透明）"],["jpg","JPG（白底）"]]}
// param: {"k":"quality","t":"number","n":"JPG 质量","d":90,"min":1,"max":100,"unit":"%","showIf":{"k":"format","in":["jpg"]}}
// param: {"k":"suffix","t":"text","n":"文件名后缀","d":"","hint":"拼在文档名之后，如 @2x"}
// param: {"k":"dir","t":"path","n":"输出目录","d":"","hint":"留空则每次弹窗选择"}
// param: {"k":"openAfter","t":"bool","n":"导出后在资源管理器中打开","d":true}
#target photoshop

// ==PARAMS-BEGIN==  面板会整块替换这一段；直接双击运行则使用下面的默认值
var CFG = {
  target: "doc",
  mode: "fit",
  width: 1920,
  height: 0,
  format: "png",
  quality: 90,
  suffix: "",
  dir: "",
  openAfter: true,
  quiet: false
};
// ==PARAMS-END==

(function () {
  var result = { ok: false, cancelled: false, message: "", files: [], size: "", layer: "" };
  var srcDoc = null;
  var tmpDoc = null;

  try {
    srcDoc = app.activeDocument;
    if (!srcDoc) { throw new Error("没有打开的文档"); }

    /* 1. 记录源文档与目标图层（复制后用「名字路径」找回同一个图层） */
    var srcLayer = null;
    var layerPath = null;
    if (CFG.target === "layer") {
      srcLayer = srcDoc.activeLayer;
      if (!srcLayer) { throw new Error("没有选中的图层"); }
      layerPath = layerNamePath(srcLayer);
    }

    /* 2. 复制文档动手，原文档全程不碰 */
    tmpDoc = srcDoc.duplicate("__studio_export__", false);
    app.activeDocument = tmpDoc;

    /* 3. 图层模式：裁到该图层的内容范围 */
    if (layerPath) {
      var l = layerByNamePath(tmpDoc, layerPath);
      /* 兜底：复制文档会保留当前图层（PS 27.10 实测），名字路径失效时用它 */
      if (!l) { l = tmpDoc.activeLayer; }
      if (!l) { throw new Error("在副本中找不到对应图层"); }
      result.layer = l.name;
      var b = l.bounds;
      var x1 = Math.max(0, Math.floor(b[0].as("px")));
      var y1 = Math.max(0, Math.floor(b[1].as("px")));
      var x2 = Math.min(Math.round(tmpDoc.width.as("px")), Math.ceil(b[2].as("px")));
      var y2 = Math.min(Math.round(tmpDoc.height.as("px")), Math.ceil(b[3].as("px")));
      if (x2 - x1 < 1 || y2 - y1 < 1) { throw new Error("图层范围为空（图层可能完全透明）"); }
      tmpDoc.crop([u(x1), u(y1), u(x2), u(y2)]);
    }

    /* 4. 算目标尺寸 */
    var ow = Math.round(tmpDoc.width.as("px"));
    var oh = Math.round(tmpDoc.height.as("px"));
    var nw = ow, nh = oh;
    var W = Number(CFG.width) || 0;
    var H = Number(CFG.height) || 0;
    var k = 1;

    if (CFG.mode === "scale") {
      k = W > 0 ? W : 1;
    } else if (CFG.mode === "exact") {
      nw = W > 0 ? Math.round(W) : ow;
      nh = H > 0 ? Math.round(H) : oh;
      k = 0;
    } else {
      if (W && H) { k = Math.min(W / ow, H / oh); }
      else if (W) { k = W / ow; }
      else if (H) { k = H / oh; }
    }
    if (CFG.mode !== "exact") {
      nw = Math.max(1, Math.round(ow * k));
      nh = Math.max(1, Math.round(oh * k));
    }
    if (nw !== ow || nh !== oh) {
      tmpDoc.resizeImage(u(nw), u(nh), tmpDoc.resolution, ResampleMethod.BICUBICSHARPER);
    }

    /* 5. 输出位置与文件名 */
    var dirPath = (CFG.dir || "").replace(/^\s+|\s+$/g, "");
    if (!dirPath) {
      var picked = Folder.selectDialog("选择导出目录");
      if (!picked) { throw new Error("__cancelled__"); }
      dirPath = picked.fsName;
    }
    var outDir = new Folder(dirPath);
    if (!outDir.exists) { throw new Error("输出目录不存在：" + dirPath); }

    var base = srcDoc.name.replace(/\.[^.]+$/, "");
    var ext = CFG.format === "jpg" ? ".jpg" : ".png";
    var outFile = new File(outDir.fsName + "/" + base + (CFG.suffix || "") + ext);

    /* 6. 落盘 */
    if (CFG.format === "jpg") {
      tmpDoc.flatten();
      var jo = new JPEGSaveOptions();
      jo.quality = Math.max(0, Math.min(12, Math.round((Number(CFG.quality) || 90) / 100 * 12)));
      jo.embedColorProfile = true;
      jo.formatOptions = FormatOptions.STANDARDBASELINE;
      tmpDoc.saveAs(outFile, jo, true, Extension.LOWERCASE);
    } else {
      var po = new PNGSaveOptions();
      po.interlaced = false;
      po.compression = 6;
      tmpDoc.saveAs(outFile, po, true, Extension.LOWERCASE);
    }

    /* 7. 回执 */
    var written = new File(outFile.fsName);
    result.ok = written.exists;
    result.files.push(written.fsName);
    if (written.exists) {
      result.size = Math.round(written.length / 1024) + " KB";
      result.message = written.name + "　" + nw + "×" + nh + "　" + result.size
                     + (result.layer ? "　图层「" + result.layer + "」" : "");
    } else {
      result.message = "导出命令已执行，但没有生成文件";
    }
  } catch (e) {
    var msg = (e && e.message) ? String(e.message) : String(e);
    if (msg.indexOf("__cancelled__") === 0) {
      result.cancelled = true;
      result.message = "已取消";
    } else {
      result.message = msg;
    }
  }

  /* 8. 收尾：关副本、还原活动文档 */
  try { if (tmpDoc && tmpDoc !== srcDoc) { tmpDoc.close(SaveOptions.DONOTSAVECHANGES); } } catch (e2) {}
  try { if (srcDoc) { app.activeDocument = srcDoc; } } catch (e3) {}

  if (result.ok && CFG.openAfter) {
    try { new Folder(result.files[0].replace(/[^\\\/]+$/, "")).execute(); } catch (e4) {}
  }

  var payload = jsonStr(result);
  if (!CFG.quiet) {
    alert(result.ok ? "导出成功\n\n" + result.message : "未导出\n\n" + result.message);
  }
  return payload;

  /* ---- 内部函数 ---- */
  function u(n) { return new UnitValue(n, "px"); }

  /* ExtendScript 没有 JSON 对象（PS 27.10 实测报"JSON 未定义"），自己拼一份扁平 JSON */
  function jsonStr(o) {
    var arr = [];
    for (var i = 0; i < o.files.length; i++) { arr.push(jstr(o.files[i])); }
    return '{"ok":' + (o.ok ? 'true' : 'false')
         + ',"cancelled":' + (o.cancelled ? 'true' : 'false')
         + ',"message":' + jstr(o.message)
         + ',"size":' + jstr(o.size)
         + ',"layer":' + jstr(o.layer)
         + ',"files":[' + arr.join(',') + ']}';
  }

  function jstr(s) {
    if (s === null || s === undefined) { s = ""; }
    s = String(s);
    var out = '"';
    for (var i = 0; i < s.length; i++) {
      var c = s.charAt(i);
      var code = s.charCodeAt(i);
      if (c === '"') { out += '\\"'; }
      else if (c === '\\') { out += '\\\\'; }
      else if (code === 10) { out += '\\n'; }
      else if (code === 13) { out += '\\r'; }
      else if (code === 9) { out += '\\t'; }
      else if (code < 32 || code > 126) { out += '\\u' + ('000' + code.toString(16)).slice(-4); }
      else { out += c; }
    }
    return out + '"';
  }

  /* 图层的名字路径：自叶向根收集名字，再反转成根→叶。
     不用 itemIndex —— PS 27.10 实测 doc.layers 是 0 基自上而下、itemIndex 是另一套编号，
     两者对不上；名字路径在复制出的文档里同样能解析。 */
  function layerNamePath(l) {
    var rev = [];
    var cur = l;
    var guard = 0;
    while (cur && guard++ < 64) {
      rev[rev.length] = cur.name;
      var par = cur.parent;
      if (!par || par.typename === "Document") { break; }
      cur = par;
    }
    var path = [];
    for (var i = rev.length - 1; i >= 0; i--) { path[path.length] = rev[i]; }
    return path;
  }

  /* 逐级 getByName 解析；container.layers 同时能命中 ArtLayer 与 LayerSet */
  function layerByNamePath(d, path) {
    if (!path || !path.length) { return null; }
    var cur = null;
    var container = d;
    for (var i = 0; i < path.length; i++) {
      try { cur = container.layers.getByName(path[i]); }
      catch (e) { return null; }
      if (!cur) { return null; }
      container = cur;
    }
    return cur;
  }
})();

