#target photoshop

// ==PARAMS-BEGIN==  面板会整块替换这一段；直接双击运行则使用下面的默认值
var CFG = {
  target: "auto",        // auto | doc | items
  items: "",             // target=items 时：项目名，多个用 | 分隔
  format: "png",         // png | jpg | psd | tif | bmp
  sizeMode: "orig",      // orig | fit | exact | scale
  width: 100,            // fit=长边 px，exact=宽 px，scale=百分比
  height: 0,             // exact=高 px，0 表示按宽自适应
  keepRatio: true,       // exact 模式下是否等比（等比时取小的一边适配）
  sizeTarget: 0,         // KB，0=不限制；>0 自动搜质量/压缩级别压到目标内
  quality: 85,           // JPG 质量 0-100（填了目标体积时会被自动搜索覆盖）
  pngComp: "6",          // PNG 压缩级别 1|6|9
  dir: "",               // 输出目录，留空 = 文档目录/桌面
  suffix: "",            // 文件名后缀
  openAfter: false,      // 导出后打开文件夹
  quick: false,          // true = 不开面板，直接按上面的设置导出（宿主/回归测试用）
  quiet: false           // true = 不弹 alert
};
// ==PARAMS-END==

(function () {
  var TMP_PREFIX = "__export_tmp_";

  var result = {
    ok: false, cancelled: false, quick: false, host: false, doc: "", dir: "",
    count: 0, requested: 0, totalBytes: 0, items: [], failed: [], message: ""
  };
  var tmpDocs = [];      // 本次跑出来的所有临时文档，收尾统一关掉
  var srcDoc = null;
  var oldDialogs = null;
  var oldActiveLayer = null;   // 导出要按 id 选中各项，收尾还原用户的当前图层

  /* 入口：最后统一调用，确保所有 var 都已赋值
     （ExtendScript 的 var 提升会让「先调用、后赋值」拿到 undefined —— 真机踩过：面板里读 OPTS 直接报「undefined 不是对象」） */
  /* 默认参数区的键数（下面 CFG 里那 15 个）。用它区分「脚本双击跑」和
     「宿主把整段参数区换掉后跑」——后者键数必然多于默认值。 */
  var DEFAULT_KEYS = 15;

  function main() {
  try {
    srcDoc = app.activeDocument;
    if (!srcDoc) { throw new Error("没有打开的文档"); }

    /* 导出期间不让任何系统对话框冒出来（探针实测 trim/crop 在个别场景会弹模态框，会卡住宿主调用） */
    try { oldDialogs = app.displayDialogs; app.displayDialogs = DialogModes.NO; } catch (eD) {}
    try { oldActiveLayer = srcDoc.activeLayer; } catch (eL) {}

    var cfg = CFG;
    if (cfg.quick) {
      /* 宿主（Quicker 动作 / 回归）注入的配置：直接照做，不合并「上次设置」 */
      result.quick = true;
      result.host = true;
      runJob(srcDoc, cfg);
    } else {
      var settingsPath = defaultSettingsPath();
      var merged = mergeCfg(loadSettings(settingsPath), isHostDriven(cfg) ? cfg : null);
      result.host = isHostDriven(cfg);
      showDialog(srcDoc, merged, settingsPath);
    }
  } catch (e) {
    fail(e);
  }
  }


  /* ================= 面板 ================= */

  function showDialog(doc, cfg, settingsPath) {
    var dl = new Window("dialog", "快速导出");
    dl.orientation = "column";
    dl.alignChildren = "fill";
    dl.spacing = 8;
    dl.margins = [12, 12, 12, 12];
    try { dl.preferredSize.width = 452; } catch (eW) {}

    var head = dl.add("statictext", undefined, doc.name + "　"
                      + Math.round(doc.width.as("px")) + " × " + Math.round(doc.height.as("px")) + " px");
    try { head.graphics.font = ScriptUI.newFont("Tahoma", "BOLD", 12); } catch (eF) {}

    /* ---- 1 导出对象 ---- */
    var g1 = dl.add("panel", undefined, "导出对象");
    g1.orientation = "column";
    g1.alignChildren = "left";
    g1.margins = [12, 16, 12, 10];
    var rAuto = g1.add("radiobutton", undefined, "选中的画板 / 图层（没选则导出整个文档）");
    var rDoc = g1.add("radiobutton", undefined, "整个文档画布（含画板时是所有画板拼在一起）");
    var rList = g1.add("radiobutton", undefined, "自定义勾选（在下面列表中选）");
    if (cfg.target === "doc") { rDoc.value = true; }
    else if (cfg.target === "items") { rList.value = true; }
    else { rAuto.value = true; }

    var tree = loadTree(doc);
    var selNames = selectedNames(tree);
    var wanted = parseNames(cfg.items);
    var listBox = g1.add("listbox", [0, 0, 396, 108], [], { multiselect: true });
    fillList(listBox, tree, selNames, wanted);
    var chkAll = g1.add("button", undefined, "全选 / 全不选");
    var hintRow = g1.add("group");
    hintRow.alignChildren = "top";
    var hint = hintRow.add("statictext", undefined,
                           "默认已勾选画板与当前选中的项；\n导出会裁掉该项周围的空白",
                           { preferredSize: [396, 34] });
    hint.graphics.foregroundColor = hint.graphics.newPen(dl.graphics.PenType.SOLID_COLOR, [0.45, 0.45, 0.45], 1);

    /* ---- 2 格式与体积 ---- */
    var g2 = dl.add("panel", undefined, "格式与体积");
    g2.orientation = "column";
    g2.alignChildren = "left";
    g2.margins = [12, 16, 12, 10];

    var rowF = g2.add("group");
    rowF.add("statictext", undefined, "格式");
    var ddFmt = rowF.add("dropdownlist", undefined, optLabels(OPTS.format));
    var rowQ = g2.add("group");
    rowQ.add("statictext", undefined, "质量");
    var slQ = rowQ.add("slider", [0, 0, 180, 20], 0, 100, Number(cfg.quality) || 85, { preferredSize: [180, 20] });
    var lbQ = rowQ.add("statictext", [0, 0, 34, 20], String(Math.round(Number(cfg.quality) || 85)));
    var rowP = g2.add("group");
    var lbP = rowP.add("statictext", undefined, "PNG 压缩");
    var ddP = rowP.add("dropdownlist", undefined, optLabels(OPTS.pngComp));

    var rowT = g2.add("group");
    rowT.add("statictext", undefined, "目标体积");
    var etT = rowT.add("edittext", [0, 0, 70, 22], cfg.sizeTarget > 0 ? String(cfg.sizeTarget) : "");
    rowT.add("statictext", undefined, "KB（留空=不管体积）");
    var autoRow = g2.add("group");
    autoRow.alignChildren = "top";
    var lbAuto = autoRow.add("statictext", undefined, " ", { preferredSize: [396, 16] });
    lbAuto.graphics.foregroundColor = lbAuto.graphics.newPen(dl.graphics.PenType.SOLID_COLOR, [0.45, 0.45, 0.45], 1);

    /* ---- 3 尺寸 ---- */
    var g3 = dl.add("panel", undefined, "尺寸");
    g3.orientation = "column";
    g3.alignChildren = "left";
    g3.margins = [12, 16, 12, 10];
    var rowM = g3.add("group");
    rowM.add("statictext", undefined, "方式");
    var ddM = rowM.add("dropdownlist", undefined, optLabels(OPTS.sizeMode));
    var rowW = g3.add("group");
    var lbW = rowW.add("statictext", [0, 0, 96, 20], "长边上限 (px)");
    var etW = rowW.add("edittext", [0, 0, 80, 22], String(cfg.width));
    var rowH = g3.add("group");
    var lbH = rowH.add("statictext", [0, 0, 96, 20], "高 (px，0=自适应)");
    var etH = rowH.add("edittext", [0, 0, 80, 22], cfg.height > 0 ? String(cfg.height) : "");
    var rowK = g3.add("group");
    var cbK = rowK.add("checkbox", undefined, "精确模式等比缩放（不勾 = 拉伸变形）");
    cbK.value = (cfg.keepRatio !== false);

    /* ---- 4 输出 ---- */
    var g4 = dl.add("panel", undefined, "输出");
    g4.orientation = "column";
    g4.alignChildren = "left";
    g4.margins = [12, 16, 12, 10];
    var rowD = g4.add("group");
    var etD = rowD.add("edittext", [0, 0, 290, 22], cfg.dir || "");
    var btnD = rowD.add("button", undefined, "浏览…");
    var rowS = g4.add("group");
    rowS.add("statictext", undefined, "文件名后缀");
    var etS = rowS.add("edittext", [0, 0, 120, 22], cfg.suffix || "");
    var cbOpen = g4.add("checkbox", undefined, "导出后打开文件夹");
    cbOpen.value = (cfg.openAfter === true);
    var lbD = g4.add("statictext", undefined, " ");
    lbD.graphics.foregroundColor = lbD.graphics.newPen(dl.graphics.PenType.SOLID_COLOR, [0.45, 0.45, 0.45], 1);

    /* ---- 底部按钮 ---- */
    var bar = dl.add("group");
    bar.alignment = "right";
    var btnQuick = bar.add("button", undefined, "用上次设置直接导出");
    var btnGo = bar.add("button", undefined, "导出", { name: "ok" });
    var btnCancel = bar.add("button", undefined, "取消", { name: "cancel" });
    if (!fileExists(settingsPath)) { btnQuick.enabled = false; }

    /* ---- 联动 ---- */

    ddFmt.selection = findOpt(OPTS.format, cfg.format);
    ddP.selection = findOpt(OPTS.pngComp, String(cfg.pngComp));
    ddM.selection = findOpt(OPTS.sizeMode, cfg.sizeMode);

    function modeNow() {
      if (rDoc.value) { return "doc"; }
      if (rList.value) { return "items"; }
      return "auto";
    }
    function checkedNames() {
      var arr = [];
      for (var i = 0; i < listBox.items.length; i++) {
        if (listBox.items[i].checked) { arr[arr.length] = listBox.items[i].text; }
      }
      return arr;
    }
    function targetKB() {
      var t = trimStr(etT.text);
      var n = t ? Number(t) : 0;
      return (n > 0) ? n : 0;
    }
    function syncList() {
      var en = (modeNow() !== "doc");
      listBox.enabled = en;
      chkAll.enabled = en;
    }
    function syncSize() {
      var m = valueOfLabel(OPTS.sizeMode, selLabel(ddM, OPTS.sizeMode[0][1]));
      lbH.enabled = etH.enabled = (m === "exact");
      lbW.enabled = etW.enabled = (m !== "orig");
      cbK.enabled = (m === "exact");
      lbW.text = (m === "scale") ? "百分比 (%)" : (m === "exact" ? "宽 (px)" : "长边上限 (px)");
    }
    function syncFmt() {
      var f = valueOfLabel(OPTS.format, selLabel(ddFmt, OPTS.format[0][1]));
      lbQ.enabled = slQ.enabled = (f === "jpg");
      lbP.enabled = ddP.enabled = (f === "png");
    }
    function syncInfo() {
      var f = valueOfLabel(OPTS.format, selLabel(ddFmt, OPTS.format[0][1]));
      var kb = targetKB();
      if ((f === "psd" || f === "tif" || f === "bmp") && kb > 0) { lbAuto.text = "该格式不能按体积压缩，目标体积会被忽略"; }
      else if (kb > 0) { lbAuto.text = "会多试几次质量与压缩级别，导出慢一些"; }
      else { lbAuto.text = " "; }
      var n = 1;
      var m = modeNow();
      var cnt = checkedNames().length;
      if (m === "items") { n = cnt; }
      else if (m === "auto" && cnt > 0) { n = cnt; }
      var d = trimStr(etD.text);
      lbD.text = "将导出 " + n + " 个文件　→　" + (d ? d : "文档所在目录 / 桌面");
    }
    function syncAll() { syncList(); syncSize(); syncFmt(); syncInfo(); }

    ddFmt.onChange = function () { syncFmt(); syncInfo(); };
    ddP.onChange = syncInfo;
    ddM.onChange = syncSize;
    slQ.onChanging = function () { lbQ.text = String(Math.round(slQ.value)); };
    slQ.onChange = function () { lbQ.text = String(Math.round(slQ.value)); syncInfo(); };
    etT.onChanging = syncInfo;
    rAuto.onClick = rDoc.onClick = rList.onClick = function () { syncList(); syncInfo(); };
    listBox.onClick = function () {
      for (var i = 0; i < listBox.items.length; i++) {
        listBox.items[i].checked = listBox.items[i].selected;
      }
      syncInfo();
    };
    chkAll.onClick = function () {
      var all = true;
      for (var i = 0; i < listBox.items.length; i++) { if (!listBox.items[i].checked) { all = false; } }
      for (var j = 0; j < listBox.items.length; j++) {
        listBox.items[j].checked = !all;
        listBox.items[j].selected = !all;
      }
      syncInfo();
    };
    btnD.onClick = function () {
      var f = Folder.selectDialog("选择导出目录");
      if (f) { etD.text = f.fsName; syncInfo(); }
    };

    function readCfg() {
      var c = cloneCfg(cfg);
      c.format = valueOfLabel(OPTS.format, selLabel(ddFmt, OPTS.format[0][1]));
      c.sizeMode = valueOfLabel(OPTS.sizeMode, selLabel(ddM, OPTS.sizeMode[0][1]));
      c.width = numOr(etW.text, 100);
      c.height = numOr(etH.text, 0);
      c.keepRatio = (cbK.value === true);
      c.sizeTarget = targetKB();
      c.quality = Math.round(slQ.value);
      c.pngComp = valueOfLabel(OPTS.pngComp, selLabel(ddP, OPTS.pngComp[0][1]));
      c.suffix = trimStr(etS.text);
      c.dir = trimStr(etD.text);
      c.openAfter = (cbOpen.value === true);
      c.quick = false;
      c.quiet = (CFG.quiet === true);
      return c;
    }

    btnQuick.onClick = function () {
      var st = loadSettings(settingsPath);
      if (!st) { return; }
      st.quick = true;
      st.quiet = (CFG.quiet === true);
      dl.close(2);
      runJob(doc, mergeCfg(st, CFG));
      result.quick = true;
    };
    btnGo.onClick = function () {
      var picked = checkedNames();
      var m = modeNow();
      if (m === "items" && !picked.length) { alert("没有勾选任何画板或图层。"); return; }
      var c = readCfg();
      c.target = m;
      c.items = (m === "doc") ? "" : joinNames(picked);
      saveSettings(settingsPath, c);
      dl.close(2);
      runJob(doc, c);
    };

    syncAll();
    var code = dl.show();
    if (code !== 2) { result.cancelled = true; result.message = "已取消"; }
  }

  /* ================= 任务执行 ================= */

  /* 多选一起导出 = 所有项目共用同一套格式/尺寸/体积参数（正是"一起导出"的语义） */
  function runJob(doc, cfg) {
    var outDir = resolveOutDir(doc, cfg.dir);
    result.doc = doc.name;
    result.dir = outDir.fsName;

    /* 组任务列表 */
    var jobList = [];
    var i;
    if (cfg.target === "doc") {
      jobList[jobList.length] = { name: baseNameOf(doc.name), path: [], kind: "doc", id: -1 };
    } else {
      var tree = loadTree(doc);
      var wanted = parseNames(cfg.items);
      if (!wanted.length) { wanted = selectedNames(tree); }
      var byLower = {};
      for (i = 0; i < tree.length; i++) {
        var lk = tree[i].name.toLowerCase();
        if (!byLower[lk]) { byLower[lk] = tree[i]; }
      }
      for (i = 0; i < wanted.length; i++) {
        var node = byLower[wanted[i].toLowerCase()];
        if (node) { jobList[jobList.length] = node; }
      }
      if (!jobList.length) {
        jobList[jobList.length] = { name: baseNameOf(doc.name), path: [], kind: "doc", id: -1 };
      }
    }
    result.requested = jobList.length;

    var used = {};
    for (i = 0; i < jobList.length; i++) {
      var it = jobList[i];
      var base = safeName(it.name) || "untitled";
      var nm = uniqueName(used, base + (cfg.suffix || ""));
      var outFile = new File(outDir.fsName + "/" + nm + "." + extOf(cfg.format));
      try {
        result.items[result.items.length] =
          exportOne(doc, it, cfg, outFile, outDir.fsName + "/" + TMP_PREFIX + nm);
        result.count++;
        result.totalBytes += result.items[result.items.length - 1].bytes;
      } catch (e) {
        result.failed[result.failed.length] = it.name + "：" + errText(e);
      }
    }

    if (result.count > 0) {
      result.ok = true;
      result.message = result.count + " / " + result.requested + " 个导出成功，共 "
                     + fmtSize(result.totalBytes) + "\n" + outDir.fsName;
    } else {
      result.message = "全部导出失败" + (result.failed.length ? "：" + result.failed[0] : "");
    }
    if (result.cancelled) { result.message = "已取消"; }
    if (result.failed.length) {
      result.message += "（失败 " + result.failed.length + " 个：" + result.failed[0] + "）";
    }
  }

  /* 单项导出：建副本 → 裁到内容 → 缩放 → 落盘 → 关副本 */
  function exportOne(doc, item, cfg, outFile, tmpBase) {
    var d2 = (item.kind === "doc") ? dupDoc(doc) : makeDocFromItem(doc, item);
    tmpDocs[tmpDocs.length] = d2;

    /* doc.trim() 返回 undefined（PS 27.10 实测），只能靠裁剪后的尺寸判断是否裁到了内容 */
    var before = Math.round(d2.width.as("px")) + "x" + Math.round(d2.height.as("px"));
    var after = trimToContent(d2);
    var trimmed = (after !== before);

    var ow = Math.round(d2.width.as("px"));
    var oh = Math.round(d2.height.as("px"));
    var size = planSize(ow, oh, cfg);
    if (size.nw !== ow || size.nh !== oh) {
      d2.resizeImage(u(size.nw), u(size.nh), d2.resolution, ResampleMethod.BICUBICSHARPER);
    }

    var bytes, quality = null, steps = 0, hit = false, trace = "";
    var target = (cfg.sizeTarget > 0) ? cfg.sizeTarget * 1024 : 0;
    var searchable = (cfg.format === "jpg" || cfg.format === "png");

    if (target > 0 && searchable) {
      var found = searchBest(d2, cfg, outFile, tmpBase, target);
      /* 质量到底还不达标（大图压到很小目标）→ 按面积比例缩尺寸再搜一轮 */
      var rounds = 0;
      var guard = 0;
      while (!found.hit && found.bytes > target && rounds < 2 && guard++ < 3) {
        var need = Math.sqrt(target / found.bytes) * 0.95;
        if (need > 0.98) { need = 0.95; }
        var cw = Math.round(d2.width.as("px"));
        var ch = Math.round(d2.height.as("px"));
        var nw = Math.max(16, Math.round(cw * need));
        var nh = Math.max(16, Math.round(ch * need));
        if (nw === cw && nh === ch) { break; }
        d2.resizeImage(u(nw), u(nh), d2.resolution, ResampleMethod.BICUBICSHARPER);
        found = searchBest(d2, cfg, outFile, tmpBase, target);
        rounds++;
      }
      bytes = found.bytes; quality = found.level; steps = found.steps + rounds; hit = found.hit;
      trace = found.trace + (rounds ? "（缩尺寸 " + rounds + " 轮）" : "");
    } else {
      var lv = (cfg.format === "jpg") ? String(jpegQuality(cfg.quality)) : null;
      saveFlat(d2, outFile, cfg, lv);
      bytes = fileBytes(outFile);
      quality = (lv === null ? null : Number(lv));
    }

    return {
      name: item.name, file: outFile.fsName, bytes: bytes,
      width: Math.round(d2.width.as("px")), height: Math.round(d2.height.as("px")), quality: quality,
      format: cfg.format, kind: item.kind, steps: steps, hitTarget: hit,
      trimmed: trimmed, trace: trace
    };
  }

  /* 按目标体积搜编码级别：JPG 搜 0-12，PNG 搜 1-9 */
  function searchBest(d, cfg, outFile, tmpBase, target) {
    var lo = 1, hi = (cfg.format === "jpg") ? 12 : 9;
    var best = null;
    var steps = 0;
    var trace = [];
    var tmp = new File(tmpBase + "." + extOf(cfg.format));
    for (var i = 0; i < 4 && lo <= hi; i++) {
      var mid = Math.floor((lo + hi) / 2);
      saveFlat(d, tmp, cfg, String(mid));
      var b = fileBytes(tmp);
      steps++;
      trace[trace.length] = mid + ":" + b;
      if (b <= 0) { break; }
      if (b <= target) { if (!best || b > best.bytes) { best = { level: mid, bytes: b }; } hi = mid - 1; }
      else { lo = mid + 1; }
      if (best && best.bytes >= target * 0.9) { break; }
    }
    var use = best ? best.level : ((cfg.format === "jpg") ? 6 : 4);
    saveFlat(d, outFile, cfg, String(use));
    var bytes = fileBytes(outFile);
    if (bytes > 0 && bytes <= target && (!best || bytes > best.bytes)) { best = { level: use, bytes: bytes }; }
    try { var tmpFresh = new File(tmp.fsName); if (tmpFresh.exists) { tmpFresh.remove(); } } catch (eR) {}
    return {
      bytes: bytes, level: use, steps: steps,
      hit: (bytes > 0 && bytes <= target),
      trace: trace.join(" | ") + " → 定稿 L" + use + "=" + bytes + " / 目标 " + Math.round(target)
    };
  }

  /* 落盘。level=null 用配置里的质量/压缩；level 为字符串数字则覆盖 */
  function saveFlat(d, file, cfg, level) {
    var fmt = cfg.format;
    if (file.exists) { try { file.remove(); } catch (e0) {} }

    if (fmt === "jpg") {
      try { d.flatten(); } catch (eF) {}
      var jo = new JPEGSaveOptions();
      jo.quality = (level === null || level === undefined) ? jpegQuality(cfg.quality)
                : Math.max(0, Math.min(12, Math.round(Number(level))));
      jo.embedColorProfile = true;
      jo.formatOptions = FormatOptions.STANDARDBASELINE;
      d.saveAs(file, jo, true, Extension.LOWERCASE);
      return;
    }
    if (fmt === "png") {
      var po = new PNGSaveOptions();
      po.interlaced = false;
      po.compression = (level === null || level === undefined) ? clampComp(cfg.pngComp)
                     : Math.max(0, Math.min(9, Math.round(Number(level))));
      d.saveAs(file, po, true, Extension.LOWERCASE);
      return;
    }
    if (fmt === "psd") {
      var so = new PhotoshopSaveOptions();
      so.embedColorProfile = true;
      so.layers = true;
      d.saveAs(file, so, true, Extension.LOWERCASE);
      return;
    }
    if (fmt === "tif") {
      var to = new TiffSaveOptions();
      to.imageCompression = TIFFEncoding.TIFFLZW;
      to.embedColorProfile = true;
      to.layers = false;
      to.alphaChannels = false;
      to.transparency = false;
      try { d.flatten(); } catch (eT) {}
      d.saveAs(file, to, true, Extension.LOWERCASE);
      return;
    }
    /* bmp */
    try { d.flatten(); } catch (eB) {}
    var bo = new BMPSaveOptions();
    bo.depth = BMPDepthType.TWENTYFOUR;
    d.saveAs(file, bo, true, Extension.LOWERCASE);
  }

  /* 建立一个只含该项目内容的新文档（全程不动源文档） */
  function makeDocFromItem(doc, item) {
    /* 副本先行：PS 27.10 实测「选中某层再 duplicate」得到的是整份文档（副本里
       一样是全部图层），想真只导出某一项，必须自己把其它层从副本里删掉。
       删之前按 id / 名字路径把目标选中，这样后面的 trim(TRANSPARENT) 才有意义。 */
    var d2 = dupDoc(doc);
    if (!d2) { throw new Error("无法为「" + item.name + "」建立副本"); }
    var kept = pruneToItem(d2, item);
    if (!kept) { throw new Error("副本里找不到「" + item.name + "」，可能已被改名或删除"); }
    return d2;
  }

  /* 只保留 item 指向的那一项：组 → 顶层只留该组；普通图层 → 逐级只留祖先链上的那一支 */
  function pruneToItem(d, item) {
    if (item.path && item.path.length) {
      var l = layerByNamePath(d, item.path);
      if (l) {
        keepPath(d, l);
        try { return d.layers.getByName(item.path[0]); } catch (eK) { return d; }
      }
    }
    if (item.id && item.id > 0) {
      var ids = [];
      findById(d, item.id, ids);
      if (ids.length) {
        keepOnlyById(d, ids);
        if (d.layers.length) { return d.layers[0]; }
      }
    }
    return d;
  }

  /* 沿叶→根收集 id 链：结构被复制后 id 会变，但副本里仍能按旧 id 找回同一项 */
  function findById(container, id, out) {
    if (!container || !container.layers) { return false; }
    for (var i = 0; i < container.layers.length; i++) {
      var l = container.layers[i];
      var lid = 0;
      try { lid = l.id; } catch (eId) { continue; }
      if (lid === id) {
        out[out.length] = lid;
        var anc = l.parent;
        while (anc && anc.typename !== "Document") {
          try { out[out.length] = anc.id; } catch (eA) { break; }
          anc = anc.parent;
        }
        return true;
      }
      if (l.typename === "LayerSet" && findById(l, id, out)) { return true; }
    }
    return false;
  }

  /* 名字路径：逐级把「不在这条链上」的兄弟删掉，最后剩下该层所在的那一支 */
  function keepPath(d, leaf) {
    var chain = [];
    var cur = leaf;
    var guard = 0;
    while (cur && cur.typename !== "Document" && guard++ < 64) {
      chain[chain.length] = cur;
      cur = cur.parent;
    }
    for (var i = chain.length - 1; i >= 0; i--) {
      var node = chain[i];
      var box = (node.typename === "Document") ? d : node.parent;
      if (!box || !box.layers) { continue; }
      var sibs = box.layers;
      for (var j = sibs.length - 1; j >= 0; j--) {
        if (sibs[j] === node) { continue; }
        try { sibs[j].remove(); } catch (eRm) {}
      }
    }
  }

  function keepOnlyById(d, ids) {
    var cur = d;
    for (var k = 0; k < ids.length; k++) {
      if (!cur || !cur.layers) { return; }
      var found = null;
      for (var i = 0; i < cur.layers.length; i++) {
        var lid = 0;
        try { lid = cur.layers[i].id; } catch (eId2) {}
        if (lid === ids[k]) { found = cur.layers[i]; break; }
      }
      if (!found) { return; }
      for (var j = cur.layers.length - 1; j >= 0; j--) {
        if (cur.layers[j] !== found) {
          try { cur.layers[j].remove(); } catch (eRm2) {}
        }
      }
      cur = found;
    }
  }

  /* 裁掉与内容无关的空白：trim 透明边，返回裁剪后的 "宽x高"（trim 本身不返回边界，PS 27.10 实测） */
  function trimToContent(d) {
    try { d.trim(TrimType.TRANSPARENT); } catch (eT) {}
    var w = Math.round(d.width.as("px"));
    var h = Math.round(d.height.as("px"));
    if (w < 1 || h < 1) { throw new Error("内容为空（该项在画布内没有可见像素）"); }
    return w + "x" + h;
  }

  function planSize(ow, oh, cfg) {
    var mode = cfg.sizeMode;
    var W = Number(cfg.width) || 0;
    var H = Number(cfg.height) || 0;
    if (mode === "orig") { return { nw: ow, nh: oh }; }
    if (mode === "scale") {
      var k = (W > 0) ? W / 100 : 1;
      return { nw: Math.max(1, Math.round(ow * k)), nh: Math.max(1, Math.round(oh * k)) };
    }
    if (mode === "exact") {
      if (cfg.keepRatio !== false && W > 0) {
        var kk = (H > 0) ? Math.min(W / ow, H / oh) : W / ow;
        return { nw: Math.max(1, Math.round(ow * kk)), nh: Math.max(1, Math.round(oh * kk)) };
      }
      return {
        nw: Math.max(1, Math.round(W > 0 ? W : ow)),
        nh: Math.max(1, Math.round(H > 0 ? H : oh))
      };
    }
    /* fit：长边上限，只缩小不放大 */
    var lim = (W > 0) ? W : ((H > 0) ? H : 0);
    if (lim <= 0) { return { nw: ow, nh: oh }; }
    var k3 = lim / Math.max(ow, oh);
    if (k3 >= 1) { return { nw: ow, nh: oh }; }
    return { nw: Math.max(1, Math.round(ow * k3)), nh: Math.max(1, Math.round(oh * k3)) };
  }

  /* ================= 文档结构 ================= */

  function loadTree(doc) {
    var out = [];
    var selMap = {};
    var ids = selectedIds(doc);
    for (var s = 0; s < ids.length; s++) { selMap[String(ids[s])] = true; }
    walk(doc, [], out, selMap);
    return out;
  }

  function walk(container, path, out, selMap) {
    var layers = null;
    var n = 0;
    try { layers = container.layers; n = layers.length; } catch (e0) { return; }
    for (var i = 0; i < n; i++) {
      var l = null;
