#target photoshop
app.bringToFront();

(function () {
    try {
        if (app.documents.length === 0) {
            alert("请先打开一个包含文字图层的 Photoshop 文档。");
            return;
        }

        var doc = app.activeDocument;

        function CID(s) {
            if (s.length !== 4) throw new Error("charID 必须是 4 个字符：" + s);
            return charIDToTypeID(s);
        }

        function duplicateDesc(src) {
            if (!src) return new ActionDescriptor();
            var dst = new ActionDescriptor();
            for (var i = 0; i < src.count; i++) {
                var key = src.getKey(i);
                var type = src.getType(key);
                switch (type) {
                    case DescValueType.BOOLEANTYPE: dst.putBoolean(key, src.getBoolean(key)); break;
                    case DescValueType.INTEGERTYPE: dst.putInteger(key, src.getInteger(key)); break;
                    case DescValueType.DOUBLETYPE: dst.putDouble(key, src.getDouble(key)); break;
                    case DescValueType.STRINGTYPE: dst.putString(key, src.getString(key)); break;
                    case DescValueType.UNITDOUBLE: dst.putUnitDouble(key, src.getUnitDoubleType(key), src.getUnitDoubleValue(key)); break;
                    case DescValueType.OBJECTTYPE: dst.putObject(key, src.getObjectType(key), duplicateDesc(src.getObjectValue(key))); break;
                    case DescValueType.LISTTYPE: dst.putList(key, src.getList(key)); break;
                    case DescValueType.ENUMERATEDTYPE: dst.putEnumerated(key, src.getEnumerationType(key), src.getEnumerationValue(key)); break;
                    case DescValueType.REFERENCETYPE: dst.putReference(key, src.getReference(key)); break;
                    case DescValueType.ALIASTYPE: dst.putPath(key, src.getPath(key)); break;
                    case DescValueType.CLASSTYPE: dst.putClass(key, src.getClass(key)); break;
                }
            }
            return dst;
        }

        function stylesExactMatch(a, b) {
            if (!a && !b) return true;
            if (!a || !b || a.count !== b.count) return false;
            for (var i = 0; i < a.count; i++) {
                var key = a.getKey(i);
                if (!b.hasKey(key) || a.getType(key) !== b.getType(key)) return false;
                var type = a.getType(key);
                switch (type) {
                    case DescValueType.BOOLEANTYPE:
                        if (a.getBoolean(key) !== b.getBoolean(key)) return false;
                        break;
                    case DescValueType.INTEGERTYPE:
                        if (a.getInteger(key) !== b.getInteger(key)) return false;
                        break;
                    case DescValueType.DOUBLETYPE:
                        if (Math.abs(a.getDouble(key) - b.getDouble(key)) > 0.0001) return false;
                        break;
                    case DescValueType.STRINGTYPE:
                        if (a.getString(key) !== b.getString(key)) return false;
                        break;
                    case DescValueType.UNITDOUBLE:
                        if (a.getUnitDoubleType(key) !== b.getUnitDoubleType(key) || Math.abs(a.getUnitDoubleValue(key) - b.getUnitDoubleValue(key)) > 0.0001) return false;
                        break;
                    case DescValueType.ENUMERATEDTYPE:
                        if (a.getEnumerationType(key) !== b.getEnumerationType(key) || a.getEnumerationValue(key) !== b.getEnumerationValue(key)) return false;
                        break;
                    case DescValueType.OBJECTTYPE:
                        if (!stylesExactMatch(a.getObjectValue(key), b.getObjectValue(key))) return false;
                        break;
                    case DescValueType.LISTTYPE:
                        var la = a.getList(key), lb = b.getList(key);
                        if (la.count !== lb.count) return false;
                        for (var li = 0; li < la.count; li++) {
                            if (la.getType(li) !== lb.getType(li)) return false;
                            if (la.getType(li) === DescValueType.OBJECTTYPE && !stylesExactMatch(la.getObjectValue(li), lb.getObjectValue(li))) return false;
                            if (la.getType(li) === DescValueType.STRINGTYPE && la.getString(li) !== lb.getString(li)) return false;
                        }
                        break;
                    default:
                        return false;
                }
            }
            return true;
        }

        function selectSingleLayerById(layerId) {
            var d = new ActionDescriptor();
            var r = new ActionReference();
            r.putIdentifier(CID("Lyr "), layerId);
            d.putReference(CID("null"), r);
            d.putBoolean(CID("MkVs"), false);
            executeAction(CID("slct"), d, DialogModes.NO);
        }

        function addLayerToSelection(layerId) {
            var d = new ActionDescriptor();
            var r = new ActionReference();
            r.putIdentifier(CID("Lyr "), layerId);
            d.putReference(CID("null"), r);
            d.putEnumerated(stringIDToTypeID("selectionModifier"), stringIDToTypeID("selectionModifierType"), stringIDToTypeID("addToSelection"));
            d.putBoolean(CID("MkVs"), false);
            executeAction(CID("slct"), d, DialogModes.NO);
        }

        function buildLayerIndex(container, out) {
            out = out || {};
            var list = null;
            try { list = container.layers; } catch (e0) { return out; }
            if (!list) return out;
            for (var i = 0; i < list.length; i++) {
                var layer = list[i];
                var isSet = false;
                var isText = false;
                var locked = false;
                try { isSet = layer.typename === "LayerSet"; } catch (e1) {}
                if (!isSet) { try { isText = layer.kind === LayerKind.TEXT; } catch (e2) {} }
                try { locked = !!layer.allLocked; } catch (e3) {}
                out[layer.id] = { id: layer.id, name: layer.name, isSet: isSet, isText: isText, locked: locked, dom: layer };
                if (isSet) buildLayerIndex(layer, out);
            }
            return out;
        }

        function collectTextNodesDeep(container, acc, seen) {
            acc = acc || [];
            seen = seen || {};
            var list = null;
            try { list = container.layers; } catch (e0) { return acc; }
            if (!list) return acc;
            for (var i = 0; i < list.length; i++) {
                var layer = list[i];
                var isSet = false;
                try { isSet = layer.typename === "LayerSet"; } catch (e1) {}
                if (isSet) {
                    collectTextNodesDeep(layer, acc, seen);
                } else {
                    var isText = false;
                    try { isText = layer.kind === LayerKind.TEXT; } catch (e2) {}
                    if (isText && !seen[layer.id]) {
                        seen[layer.id] = true;
                        var locked = false;
                        try { locked = !!layer.allLocked; } catch (e3) {}
                        if (!locked) acc.push({ id: layer.id, name: layer.name, dom: layer });
                    }
                }
            }
            return acc;
        }

        function resolveSelectedTextLayers() {
            var index = buildLayerIndex(doc, {});
            var ids = [];
            try {
                var ref = new ActionReference();
                ref.putProperty(CID("Prpr"), stringIDToTypeID("targetLayersIDs"));
                ref.putEnumerated(CID("Dcmn"), CID("Ordn"), CID("Trgt"));
                var desc = executeActionGet(ref);
                if (desc.hasKey(stringIDToTypeID("targetLayersIDs"))) {
                    var list = desc.getList(stringIDToTypeID("targetLayersIDs"));
                    for (var i = 0; i < list.count; i++) {
                        try { ids.push(list.getReference(i).getIdentifier()); } catch (e0) {}
                    }
                }
            } catch (e1) {}
            if (ids.length === 0) {
                try {
                    var r2 = new ActionReference();
                    r2.putProperty(CID("Prpr"), CID("LyrI"));
                    r2.putEnumerated(CID("Lyr "), CID("Ordn"), CID("Trgt"));
                    ids.push(executeActionGet(r2).getInteger(CID("LyrI")));
                } catch (e2) {}
            }
            if (ids.length === 0) {
                try { ids.push(doc.activeLayer.id); } catch (e3) {}
            }

            var result = [];
            var seen = {};
            function push(node) {
                if (!node || seen[node.id] || !node.isText || node.locked) return;
                seen[node.id] = true;
                result.push({ id: node.id, name: node.name });
            }
            for (var k = 0; k < ids.length; k++) {
                var node = index[ids[k]];
                if (!node) continue;
                if (node.isSet) {
                    var nested = collectTextNodesDeep(node.dom, [], {});
                    for (var n = 0; n < nested.length; n++) push({ id: nested[n].id, name: nested[n].name, isText: true, locked: false });
                } else {
                    push(node);
                }
            }
            return result;
        }

        function readTextDescById(layerId) {
            var ref = new ActionReference();
            ref.putProperty(CID("Prpr"), stringIDToTypeID("textKey"));
            ref.putIdentifier(CID("Lyr "), layerId);
            var desc = executeActionGet(ref);
            if (!desc.hasKey(stringIDToTypeID("textKey"))) return null;
            return desc.getObjectValue(stringIDToTypeID("textKey"));
        }

        function hexToRgb(value) {
            var s = String(value || "").replace(/\s/g, "").replace(/^#+/, "");
            if (s.length === 3) s = s.charAt(0) + s.charAt(0) + s.charAt(1) + s.charAt(1) + s.charAt(2) + s.charAt(2);
            if (!/^[0-9a-fA-F]{6}$/.test(s)) return null;
            return [parseInt(s.substring(0, 2), 16), parseInt(s.substring(2, 4), 16), parseInt(s.substring(4, 6), 16)];
        }

        function escapeRegex(value) {
            return String(value).replace(/[\\.\+\*\?\[\^\]\$\(\)\{\}=!<>\|:\-]/g, "\\$&");
        }

        function expandReplacement(template, match) {
            var text = String(template);
            var out = "";
            for (var i = 0; i < text.length; i++) {
                if (text.charAt(i) === "$" && i + 1 < text.length) {
                    var token = text.charAt(i + 1);
                    if (token === "$") { out += "$"; i++; continue; }
                    if (token === "&") { out += match[0]; i++; continue; }
                    if (token >= "1" && token <= "9") {
                        var idx = parseInt(token, 10);
                        out += match[idx] === undefined ? "" : match[idx];
                        i++;
                        continue;
                    }
                }
                out += text.charAt(i);
            }
            return out;
        }

        function setStyleValue(style, cfg) {
            if (cfg.font) style.putString(stringIDToTypeID("fontPostScriptName"), cfg.font);
            if (cfg.size !== null) {
                var unit = style.hasKey(stringIDToTypeID("size")) ? style.getUnitDoubleType(stringIDToTypeID("size")) : charIDToTypeID("#Pnt");
                style.putUnitDouble(stringIDToTypeID("size"), unit, cfg.size);
            }
            if (cfg.tracking !== null) style.putInteger(stringIDToTypeID("tracking"), cfg.tracking);
            if (cfg.color) {
                var color = new ActionDescriptor();
                color.putDouble(CID("Rd  "), cfg.color[0]);
                color.putDouble(CID("Grn "), cfg.color[1]);
                color.putDouble(CID("Bl  "), cfg.color[2]);
                style.putObject(CID("Clr "), CID("RGBC"), color);
            }
            if (cfg.fauxBold !== null) style.putBoolean(stringIDToTypeID("syntheticBold"), cfg.fauxBold);
            if (cfg.fauxItalic !== null) style.putBoolean(stringIDToTypeID("syntheticItalic"), cfg.fauxItalic);
            return style;
        }

        function applyLayer(layerId, cfg) {
            selectSingleLayerById(layerId);
            var textDesc = readTextDescById(layerId);
            if (!textDesc) return { changed: false, matches: 0 };
            var rawText = textDesc.getString(CID("Txt "));
            if (!rawText || rawText.length === 0) return { changed: false, matches: 0 };

            var styles = [];
            var fallback = null;
            var rangeKey = stringIDToTypeID("textStyleRange");
            if (textDesc.hasKey(rangeKey)) {
                var ranges = textDesc.getList(rangeKey);
                if (ranges.count > 0) fallback = ranges.getObjectValue(0).getObjectValue(stringIDToTypeID("textStyle"));
                for (var ri = 0; ri < ranges.count; ri++) {
                    var range = ranges.getObjectValue(ri);
                    var from = range.hasKey(stringIDToTypeID("from")) ? range.getInteger(stringIDToTypeID("from")) : 0;
                    var to = range.hasKey(stringIDToTypeID("to")) ? range.getInteger(stringIDToTypeID("to")) : rawText.length;
                    var rangeStyle = range.getObjectValue(stringIDToTypeID("textStyle"));
                    for (var ci = from; ci < to && ci < rawText.length; ci++) styles[ci] = rangeStyle;
                }
            }
            if (!fallback && textDesc.hasKey(stringIDToTypeID("defaultStyle"))) fallback = textDesc.getObjectValue(stringIDToTypeID("defaultStyle"));
            for (var si = 0; si < rawText.length; si++) if (!styles[si]) styles[si] = fallback;
            if (!fallback) return { changed: false, matches: 0 };

            var re = cfg.regex;
            re.lastIndex = 0;
            var matches = [];
            var match;
            while ((match = re.exec(rawText)) !== null) {
                if (match[0].length === 0) { re.lastIndex++; continue; }
                matches.push({ index: match.index, end: match.index + match[0].length, value: match });
            }
            if (matches.length === 0) return { changed: false, matches: 0 };

            var outText = "";
            var outStyles = [];
            var hitRanges = [];
            var cursor = 0;
            function appendOriginal(from, to) {
                for (var oi = from; oi < to; oi++) {
                    outText += rawText.charAt(oi);
                    outStyles.push(styles[oi] || fallback);
                }
            }
            for (var mi = 0; mi < matches.length; mi++) {
                var item = matches[mi];
                appendOriginal(cursor, item.index);
                var startOut = outText.length;
                var replacement = cfg.replace ? expandReplacement(cfg.replacement, item.value) : rawText.substring(item.index, item.end);
                var baseStyle = styles[item.index] || fallback;
                for (var pi = 0; pi < replacement.length; pi++) {
                    outText += replacement.charAt(pi);
                    outStyles.push(baseStyle);
                }
                if (outText.length > startOut) hitRanges.push({ from: startOut, to: outText.length });
                cursor = item.end;
            }
            appendOriginal(cursor, rawText.length);

            for (var hi = 0; hi < hitRanges.length; hi++) {
                for (var h = hitRanges[hi].from; h < hitRanges[hi].to; h++) {
                    outStyles[h] = setStyleValue(duplicateDesc(outStyles[h] || fallback), cfg);
                }
            }

            textDesc.putString(CID("Txt "), outText);
            if (outText.length === 0) {
                if (textDesc.hasKey(rangeKey)) textDesc.erase(rangeKey);
            } else {
                var styleList = new ActionList();
                var active = outStyles[0] || fallback;
                var activeFrom = 0;
                for (var oi2 = 1; oi2 <= outText.length; oi2++) {
                    var next = oi2 < outText.length ? (outStyles[oi2] || fallback) : null;
                    if (next === null || !stylesExactMatch(active, next)) {
                        var outRange = new ActionDescriptor();
                        outRange.putInteger(stringIDToTypeID("from"), activeFrom);
                        outRange.putInteger(stringIDToTypeID("to"), oi2);
                        outRange.putObject(stringIDToTypeID("textStyle"), stringIDToTypeID("textStyle"), active);
                        styleList.putObject(rangeKey, outRange);
                        active = next;
                        activeFrom = oi2;
                    }
                }
                textDesc.putList(rangeKey, styleList);
            }

            var setDesc = new ActionDescriptor();
            var targetRef = new ActionReference();
            targetRef.putEnumerated(CID("TxLr"), CID("Ordn"), CID("Trgt"));
            setDesc.putReference(CID("null"), targetRef);
            setDesc.putObject(CID("T   "), CID("TxLr"), textDesc);
            executeAction(CID("setd"), setDesc, DialogModes.NO);
            return { changed: true, matches: matches.length };
        }

        function readFontItems() {
            var items = [{ label: "保持原字体", ps: "" }];
            try {
                for (var i = 0; i < app.fonts.length; i++) {
                    var f = app.fonts[i];
                    var ps = "";
                    var family = "";
                    var style = "";
                    try { ps = String(f.postScriptName); } catch (e0) {}
                    try { family = String(f.family); } catch (e1) {}
                    try { style = String(f.style); } catch (e2) {}
                    if (ps) items.push({ label: family + " / " + style + "  [" + ps + "]", ps: ps });
                }
            } catch (e3) {}
            return items;
        }

        function buildDialog() {
            var dlg = new Window("dialog", "批量文字片段编辑");
            dlg.orientation = "column";
            dlg.alignChildren = ["fill", "top"];
            dlg.spacing = 8;
            dlg.margins = 14;

            var help = dlg.add("statictext", undefined, "按文字内容命中局部片段；只会改命中的字符范围，不会把整层样式覆盖掉。", { multiline: true });
            help.preferredSize.width = 560;

            var scope = dlg.add("panel", undefined, "处理范围");
            scope.orientation = "row";
            scope.alignChildren = ["left", "center"];
            var rbSelected = scope.add("radiobutton", undefined, "当前选中/当前文字图层");
            var rbAll = scope.add("radiobutton", undefined, "文档内全部文字图层");
            rbSelected.value = true;

            var matchPanel = dlg.add("panel", undefined, "匹配局部文字");
            matchPanel.orientation = "column";
            matchPanel.alignChildren = ["fill", "top"];
            var modeRow = matchPanel.add("group");
            var rbLiteral = modeRow.add("radiobutton", undefined, "普通文字");
            var rbRegex = modeRow.add("radiobutton", undefined, "正则表达式");
            var chkIgnore = modeRow.add("checkbox", undefined, "忽略大小写");
            rbLiteral.value = true;
            var matchInput = matchPanel.add("edittext", undefined, "");
            matchInput.helpTip = "例如：价格|尺寸，或直接输入一段文字";

            var replacePanel = dlg.add("panel", undefined, "文字内容（可选）");
            replacePanel.orientation = "row";
            replacePanel.alignChildren = ["center", "center"];
            var chkReplace = replacePanel.add("checkbox", undefined, "替换命中的文字");
            var replacementInput = replacePanel.add("edittext", undefined, "");
            replacementInput.characters = 34;
            replacementInput.enabled = false;
            chkReplace.onClick = function () { replacementInput.enabled = chkReplace.value; };

            var stylePanel = dlg.add("panel", undefined, "命中片段样式（留空/保持原样）");
            stylePanel.orientation = "column";
            stylePanel.alignChildren = ["fill", "top"];
            var fontRow = stylePanel.add("group");
            fontRow.add("statictext", undefined, "字体 PS 名");
            var fontInput = fontRow.add("edittext", undefined, "");
            fontInput.characters = 24;
            var fontList = fontRow.add("dropdownlist", undefined, []);
            fontList.preferredSize.width = 230;
            var fonts = readFontItems();
            for (var fi = 0; fi < fonts.length; fi++) {
                var fontItem = fontList.add("item", fonts[fi].label);
                fontItem.fontPs = fonts[fi].ps;
            }
            fontList.selection = 0;
            fontList.onChange = function () {
                if (fontList.selection && fontList.selection.fontPs) fontInput.text = fontList.selection.fontPs;
            };

            var attrRow = stylePanel.add("group");
            attrRow.add("statictext", undefined, "字号");
            var sizeInput = attrRow.add("edittext", undefined, "");
            sizeInput.characters = 8;
            attrRow.add("statictext", undefined, "字距");
            var trackingInput = attrRow.add("edittext", undefined, "");
            trackingInput.characters = 8;
            attrRow.add("statictext", undefined, "颜色 HEX");
            var colorInput = attrRow.add("edittext", undefined, "");
            colorInput.characters = 10;

            var toggleRow = stylePanel.add("group");
            toggleRow.add("statictext", undefined, "仿粗体");
            var boldList = toggleRow.add("dropdownlist", undefined, ["不修改", "开启", "关闭"]);
            boldList.selection = 0;
            toggleRow.add("statictext", undefined, "仿斜体");
            var italicList = toggleRow.add("dropdownlist", undefined, ["不修改", "开启", "关闭"]);
            italicList.selection = 0;
            toggleRow.add("statictext", undefined, "提示：字体下拉框中的 style 就是字重");

            var buttons = dlg.add("group");
            buttons.alignment = "right";
            buttons.add("button", undefined, "取消", { name: "cancel" });
            var ok = buttons.add("button", undefined, "批量应用", { name: "ok" });
            ok.onClick = function () {
                if (!matchInput.text) { alert("请先输入要匹配的文字或正则表达式。"); return; }
                if (!chkReplace.value && !fontInput.text && !sizeInput.text && !trackingInput.text && !colorInput.text && boldList.selection.index === 0 && italicList.selection.index === 0) {
                    alert("请至少填写一项内容替换或样式修改。"); return;
                }
                dlg.close(1);
            };
            dlg.defaultElement = ok;
            dlg.cancelElement = buttons.children[0];

            return {
                dialog: dlg,
                selected: rbSelected,
                all: rbAll,
                literal: rbLiteral,
                ignoreCase: chkIgnore,
                match: matchInput,
                replace: chkReplace,
                replacement: replacementInput,
                font: fontInput,
                size: sizeInput,
                tracking: trackingInput,
                color: colorInput,
                bold: boldList,
                italic: italicList
            };
        }

        var ui = buildDialog();
        if (ui.dialog.show() !== 1) return;

        var pattern = ui.literal.value ? escapeRegex(ui.match.text) : ui.match.text;
        var flags = "g" + (ui.ignoreCase.value ? "i" : "");
        var regex;
        try { regex = new RegExp(pattern, flags); } catch (eRegex) {
            alert("正则表达式有误：" + eRegex.message);
            return;
        }

        var size = null;
        if (ui.size.text) {
            size = parseFloat(ui.size.text);
            if (isNaN(size) || size <= 0) { alert("字号必须是大于 0 的数字。"); return; }
        }
        var tracking = null;
        if (ui.tracking.text) {
            tracking = parseInt(ui.tracking.text, 10);
            if (isNaN(tracking)) { alert("字距必须是整数。"); return; }
        }
        var color = null;
        if (ui.color.text) {
            color = hexToRgb(ui.color.text);
            if (!color) { alert("颜色 HEX 无效，请输入例如 #FF3B30。"); return; }
        }

        var targetLayers = ui.all.value ? collectTextNodesDeep(doc, [], {}) : resolveSelectedTextLayers();
        if (targetLayers.length === 0) {
            alert("没有找到可处理的文字图层。请选中文字图层，或切换到“文档内全部文字图层”。");
            return;
        }

        var cfg = {
            regex: regex,
            replace: ui.replace.value,
            replacement: ui.replacement.text,
            font: String(ui.font.text || "").replace(/^\s+|\s+$/g, ""),
            size: size,
            tracking: tracking,
            color: color,
            fauxBold: ui.bold.selection.index === 0 ? null : ui.bold.selection.index === 1,
            fauxItalic: ui.italic.selection.index === 0 ? null : ui.italic.selection.index === 1
        };

        var success = 0;
        var matchTotal = 0;
        var failures = [];
        function executeAll() {
            for (var i = 0; i < targetLayers.length; i++) {
                try {
                    var result = applyLayer(targetLayers[i].id, cfg);
                    if (result.changed) success++;
                    matchTotal += result.matches;
                } catch (eApply) {
                    failures.push(targetLayers[i].name + "：" + eApply);
                }
            }
        }

        try {
            doc.suspendHistory("批量文字片段编辑", "executeAll()");
        } catch (eHistory) {
            executeAll();
        }

        try {
            if (targetLayers.length > 0) {
                selectSingleLayerById(targetLayers[0].id);
                for (var si = 1; si < targetLayers.length; si++) addLayerToSelection(targetLayers[si].id);
            }
        } catch (eRestore) {}

        var summary = "已处理 " + success + " 个文字图层，命中 " + matchTotal + " 个片段。";
        if (failures.length > 0) summary += "\n\n失败图层：\n" + failures.join("\n");
        alert(summary);
    } catch (eGlobal) {
        alert("脚本执行异常：" + (eGlobal.message ? eGlobal.message : eGlobal) + (eGlobal.line ? "\n第 " + eGlobal.line + " 行" : ""));
    }
})();

